-- V59: Add verb classification columns to vocabulary and seed HIGH confidence verbs
ALTER TABLE vocabulary ADD COLUMN IF NOT EXISTS verb_type VARCHAR(50) DEFAULT NULL;
ALTER TABLE vocabulary ADD COLUMN IF NOT EXISTS verb_type_ja VARCHAR(50) DEFAULT NULL;
ALTER TABLE vocabulary ADD COLUMN IF NOT EXISTS verb_note TEXT DEFAULT NULL;
ALTER TABLE vocabulary ADD COLUMN IF NOT EXISTS paired_verb_id BIGINT DEFAULT NULL;

